#!/usr/bin/env node
/**
 * Builds the chat widget into one self-contained HTML file and writes it into the API as
 * apps/api/src/mcp/widget-html.generated.ts (WIDGET_HASH + getWidgetHtml()).
 *
 *   node scripts/build.mjs           build and write the generated file
 *   node scripts/build.mjs --check   build in memory; exit 1 if the committed file is stale
 */
import { createHash } from "node:crypto";
import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { build } from "vite";

const widgetDir = fileURLToPath(new URL("..", import.meta.url));
const outFile = fileURLToPath(
  new URL("../../api/src/mcp/widget-html.generated.ts", import.meta.url),
);
const MAX_BYTES = 300 * 1024;
const check = process.argv.includes("--check");
// Same bundle whoever runs this (a test runner sets NODE_ENV=test, which would select React's development build).
process.env.NODE_ENV = "production";

const output = await build({
  configFile: `${widgetDir}vite.config.ts`,
  root: widgetDir,
  logLevel: "warn",
  mode: "production",
  build: { write: false },
});
const outputs = Array.isArray(output) ? output : [output];
const html = outputs
  .flatMap((o) => ("output" in o ? o.output : []))
  .find((file) => file.type === "asset" && file.fileName.endsWith(".html"));
if (!html) throw new Error("The widget build produced no HTML.");
const source = String(
  typeof html.source === "string" ? html.source : new TextDecoder().decode(html.source),
);

// Look at the markup only: the inlined script and stylesheet may contain tag-like strings.
const markup = source
  .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, "<script></script>")
  .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, "<style></style>");
const external = markup.match(
  /<(?:script|link|img|iframe)\b[^>]*(?:src|href)=["'][^"']+["'][^>]*>/gi,
);
if (external) throw new Error(`Widget references external assets: ${external.join(", ")}`);
if (/\b(?:src|href)=["']\.?\/?assets\//.test(markup))
  throw new Error("Widget references a built asset that was not inlined.");

const bytes = Buffer.byteLength(source);
const hash = createHash("sha256").update(source).digest("hex").slice(0, 12);
// A template literal, so the formatter has nothing to re-quote; escape what a template literal interprets.
const literal = source.replace(/\\/g, "\\\\").replace(/`/g, "\\`").replace(/\$\{/g, "\\${");
const generated =
  `// Generated by apps/widgets/scripts/build.mjs from apps/widgets. Do not edit.\n` +
  `// Rebuild with: pnpm --filter @glideworth/widgets build\n\n` +
  `/** Content hash of the bundle: the widget URI includes it, because hosts cache templates by URI. */\n` +
  `export const WIDGET_HASH = "${hash}";\n\n` +
  `const WIDGET_HTML = \`${literal}\`;\n\n` +
  `export function getWidgetHtml(): string {\n  return WIDGET_HTML;\n}\n`;

const summary = `${(bytes / 1024).toFixed(1)} KB, hash ${hash}`;
if (bytes > MAX_BYTES) {
  console.error(`Chat widget is over budget: ${summary} (limit ${MAX_BYTES / 1024} KB).`);
  process.exit(1);
}

if (check) {
  const committed = await readFile(outFile, "utf8").catch(() => "");
  if (committed !== generated) {
    console.error(
      `apps/api/src/mcp/widget-html.generated.ts is stale (fresh build: ${summary}). ` +
        "Run: pnpm --filter @glideworth/widgets build",
    );
    process.exit(1);
  }
  console.log(`Chat widget is up to date (${summary}).`);
} else {
  await writeFile(outFile, generated);
  console.log(`Chat widget: ${summary} → apps/api/src/mcp/widget-html.generated.ts`);
}
